__attribute__((ms_abi)) void* mw_GlobalAlloc(uint32_t flags, size_t bytes) {
    void* p = (flags & 0x40) ? calloc(1, bytes ? bytes : 1) : malloc(bytes ? bytes : 1);
    MW_TRACE("GlobalAlloc(flags=%u, bytes=0x%lx) = %p", flags, (unsigned long)bytes, p);
    w3_reg_add(p);
    return p;
}
/* SW-1208: GlobalLock resolves a GMEM_MOVEABLE cookie to its base pointer
 * (fixed pointers pass through unchanged, as before). */
__attribute__((ms_abi)) void* mw_GlobalLock(void* p) {
    void* base = mw_ghandle_base_of(p);
    return base ? base : p;
}
__attribute__((ms_abi)) int mw_GlobalUnlock(void* p) { return 1; }
__attribute__((ms_abi)) size_t mw_GlobalSize(void* p) {
    if (!p) return 0;
    int s = w3_reg_find(p);
    if (s >= 0 && (g_alloc_reg[s].size >> 32))
        return g_alloc_reg[s].size & ~0x100000000ull;
    return malloc_usable_size(p);
}
/* SW-1208: GlobalFree accepts BOTH registered pointers and GMEM_MOVEABLE
 * handle cookies; untracked values degrade to the documented Win32 failure
 * contract (return the same value + ERROR_INVALID_HANDLE) instead of the
 * old process-killing HEAP-TRAP — real Windows NEVER terminates here. */
__attribute__((ms_abi)) void* mw_GlobalFree(void* p) {
    void* base = mw_ghandle_base_of(p);
    if (base) {
        int gi = mw_ghandle_slot_of((uintptr_t)p);
        if (w3_reg_has(base)) w3_reg_del(base);
        free(base);
        if (gi >= 0) g_ghandle[gi].live = 0;
        MW_TRACE("GlobalFree(handle=0x%lx) -> base %p freed -> NULL",
                 (unsigned long)(uintptr_t)p, (unsigned long)(uintptr_t)base);
        return NULL;
    }
    if (!w3_reg_has(p)) {
        mw_SetLastError(6); /* ERROR_INVALID_HANDLE */
        MW_TRACE("GlobalFree(%p) -> fail (ERROR_INVALID_HANDLE)", p);
        return p;
    }
    w3_reg_del(p);
    free(p);
    MW_TRACE("GlobalFree(%p) -> NULL", p);
    return NULL;
}
__attribute__((ms_abi)) void* mw_LocalAlloc(uint32_t flags, size_t bytes) { return mw_GlobalAlloc(flags, bytes); } /* registry inside GlobalAlloc */
__attribute__((ms_abi)) void* mw_LocalLock(void* p) { return p; }
__attribute__((ms_abi)) int mw_LocalUnlock(void* p) { return 1; }
__attribute__((ms_abi)) size_t mw_LocalSize(void* p) { return p ? malloc_usable_size(p) : 0; }
__attribute__((ms_abi)) void* mw_LocalFree(void* p) {
    if (!p) return NULL;
    /* SW-1208: same handle-cookie + degrade-to-fail contract as GlobalFree
     * (real LocalFree of an invalid handle returns it + last error 6). */
    void* hbase = mw_ghandle_base_of(p);
    if (hbase) {
        int gi = mw_ghandle_slot_of((uintptr_t)p);
        if (w3_reg_has(hbase)) w3_reg_del(hbase);
        free(hbase);
        if (gi >= 0) g_ghandle[gi].live = 0;
        MW_TRACE("LocalFree(handle=0x%lx) -> base %p freed -> NULL",
                 (unsigned long)(uintptr_t)p, (unsigned long)(uintptr_t)hbase);
        return NULL;
    }
    if (!w3_reg_has(p)) {
        mw_SetLastError(6); /* ERROR_INVALID_HANDLE */
        MW_TRACE("LocalFree(%p) -> fail (ERROR_INVALID_HANDLE)", p);
        return p;
    }
    /* BUG-043 family: mirror mw_free — a guarded chunk is mmap'd; plain
     * free() on it faults inside libc (same class as BUG-041 mw_realloc). */
    if (w3_is_guarded(p)) { w3_guard_free(p); return NULL; }
    w3_reg_del(p);
    free(p);
    return NULL;
}

__attribute__((ms_abi)) int mw_GlobalMemoryStatusEx(void* ms) {
    if (!ms) return 0;
    uint8_t* p = (uint8_t*)ms;
    *(uint32_t*)(p + 0) = 64; /* dwLength */
    for (int i = 1; i < 8; i++) *(uint32_t*)(p + 4 * i) = 0;
    struct sysinfo si;
    if (sysinfo(&si) == 0) {
        uint64_t total = (uint64_t)si.totalram * si.mem_unit;
        uint64_t freeb = (uint64_t)si.freeram * si.mem_unit;
        *(uint32_t*)(p + 4) = 58; /* dwMemoryLoad % */
        *(uint64_t*)(p + 8)  = total;
        *(uint64_t*)(p + 16) = freeb;
        *(uint64_t*)(p + 32) = total;
        *(uint64_t*)(p + 40) = freeb;
    }
    return 1;
}

/* ---- system info / CPU features / debug ---- */
__attribute__((ms_abi)) void mw_GetSystemInfo(void* si) {
    MW_TRACE("GetSystemInfo()");
    if (!si) return;
    memset(si, 0, 48);
    uint8_t* p = (uint8_t*)si;
    *(uint16_t*)(p + 0)  = 9;          /* wProcessorArchitecture = AMD64 */
    *(uint16_t*)(p + 2)  = 0;
    *(uint32_t*)(p + 4)  = 4096;       /* dwPageSize */
    *(void**)(p + 8)     = (void*)0x10000;
    *(void**)(p + 16)    = (void*)0x7FFFFFFEFFFF;
    *(uint64_t*)(p + 24) = 1;          /* dwActiveProcessorMask */
    *(uint32_t*)(p + 32) = (uint32_t)sysconf(_SC_NPROCESSORS_ONLN);
    *(uint32_t*)(p + 36) = 65536;      /* dwAllocationGranularity */
    *(uint16_t*)(p + 40) = 6;          /* wProcessorLevel */
    *(uint16_t*)(p + 42) = 0x0101;
}
__attribute__((ms_abi)) void mw_GetNativeSystemInfo(void* si) { mw_GetSystemInfo(si); }
/* ISS1-WAVE3B: real GetLogicalProcessorInformationEx (Issue #1 §8.3 —
 * callers retry on ERROR_INSUFFICIENT_BUFFER until the returned size fits;
 * a bare failure stub makes them loop forever, observed live with
 * ImageMagick's CRT init). We expose one RelationProcessorCore entry with
 * the full processor mask. */
__attribute__((ms_abi)) uint32_t mw_GetLogicalProcessorInformationEx(int cls, void* buf, uint32_t* len) {
    /* SWEEP-016 SW-652b: full multi-entry topology. Coreinfo64 (a topology
     * dumper) walked past the old single-entry 48-byte buffer and crashed on
     * garbage (RIP 0x140003d6f, cmpw [rbx+2]). Real layout, all three
     * Relation classes the tool wants:
     *   RelationProcessorCore(0) xN   : 8 + PROCESSOR_RELATIONSHIP(40) = 48
     *   RelationNumaNode(1) x1        : 8 + NUMA_NODE_RELATIONSHIP(40) = 48
     *   RelationProcessorPackage(3) x1: 48 (same PROCESSOR_RELATIONSHIP)
     *   RelationGroup(4) x1           : 8 + {2 DWORDs} + GROUP_INFO(48) = 64
     * PROCESSOR_RELATIONSHIP x64: Flags(1) EfficiencyClass(1) Reserved(20)
     *                             GroupCount(2) GROUP_AFFINITY(16) = 40 */
    MW_TRACE("GetLogicalProcessorInformationEx(cls=%d)", cls);
    if (!len) { mw_SetLastError(87); return 0; }
    /* RelationAll = 0xFFFF (phnt/ntapi, undocumented-but-real): Coreinfo64
     * probes with it first; real Windows returns the full set. */
    if (cls == 0xFFFF) cls = -1;
    uint32_t ncpu = (uint32_t)sysconf(_SC_NPROCESSORS_ONLN);
    if (!ncpu) ncpu = 1;
    if (ncpu > 64) ncpu = 64;
    uint64_t all = (ncpu >= 64) ? ~0ull : ((1ull << ncpu) - 1);
    /* which classes the caller asked for: -1 = all */
    int want_core = (cls == -1 || cls == 0);
    int want_numa = (cls == -1 || cls == 1);
    int want_pkg  = (cls == -1 || cls == 3);
    int want_grp  = (cls == -1 || cls == 4);
    uint32_t needed = 0;
    if (want_core) needed += ncpu * 48;
    if (want_numa) needed += 48;
    if (want_pkg)  needed += 48;
    if (want_grp)  needed += 64;
    if (!needed) { /* unknown class: real Windows = ERROR_INVALID_PARAMETER */
        *len = 0;
        mw_SetLastError(87);
        return 0; /* SW-652b: returning success-with-0-entries made Coreinfo
                     walk uninitialized stack as entry data (RIP 0x140004030) */
    }
    if (!buf || *len < needed) {
        if (needed) *len = needed;
        mw_SetLastError(122); /* ERROR_INSUFFICIENT_BUFFER */
        return 0;
    }
    uint8_t* p = (uint8_t*)buf;
    memset(p, 0, needed);
    if (want_core) {
        for (uint32_t i = 0; i < ncpu; i++) {
            *(uint32_t*)(p + 0) = 0;            /* RelationProcessorCore */
            *(uint32_t*)(p + 4) = 48;           /* Size */
            /* Flags=0: no SMT; EfficiencyClass=0; Reserved[20]=0 */
            *(uint16_t*)(p + 8 + 22) = 1;       /* GroupCount */
            *(uint64_t*)(p + 8 + 24) = 1ull << i;
            *(uint16_t*)(p + 8 + 32) = 0;       /* Group 0 */
            p += 48;
        }
    }
    if (want_numa) {
        /* OLD-SDK NUMA_NODE_RELATIONSHIP: NodeNumber(4) Reserved[18]
         * GroupCount(2)@sub+22 GROUP_AFFINITY(16)@sub+24 — sub=40, entry=48.
         * Coreinfo64 (Sysinternals, old headers) reads GroupCount at +22; the
         * shifted Win11 layout made its NUMA map parser read garbage. */
        *(uint32_t*)(p + 0) = 1;                /* RelationNumaNode */
        *(uint32_t*)(p + 4) = 48;
        *(uint32_t*)(p + 8) = 0;                /* NodeNumber 0 */
        /* Reserved[18] @+12..29; GroupCount @+30; GA @+32 (same as core/pkg) */
        *(uint16_t*)(p + 30) = 1;
        *(uint64_t*)(p + 32) = all;
        *(uint16_t*)(p + 40) = 0;
        p += 48;
    }
    if (want_pkg) {
        *(uint32_t*)(p + 0) = 3;                /* RelationProcessorPackage */
        *(uint32_t*)(p + 4) = 48;
        *(uint16_t*)(p + 8 + 22) = 1;
        *(uint64_t*)(p + 8 + 24) = all;
        *(uint16_t*)(p + 8 + 32) = 0;
        p += 48;
    }
    if (want_grp) {
        *(uint32_t*)(p + 0) = 4;                /* RelationGroup */
        *(uint32_t*)(p + 4) = 64;
        *(uint32_t*)(p + 8) = 1;                /* ActiveGroupCount */
        *(uint32_t*)(p + 12) = 1;               /* MaximumGroupCount */
        /* PROCESSOR_GROUP_INFO at +16: MaxCount, ActiveCount, Reserved[38], Mask */
        *(uint8_t*)(p + 16) = (uint8_t)ncpu;
        *(uint8_t*)(p + 17) = (uint8_t)ncpu;
        *(uint64_t*)(p + 16 + 40) = all;
        p += 64;
    }
    *len = (uint32_t)(p - (uint8_t*)buf);
    return 1;
}
__attribute__((ms_abi)) int mw_GetNumaNodeProcessorMask(uint8_t node, uint64_t* mask) {
    /* non-Ex form (Coreinfo64 import list): UCHAR Node, PULONGLONG mask */
    if (!mask) { mw_SetLastError(87); return 0; }
    if (node != 0) { *mask = 0; return 0; } /* only node 0 exists */
    long n = sysconf(_SC_NPROCESSORS_ONLN);
    if (n <= 0) n = 1;
    *mask = (n >= 64) ? ~0ull : ((1ull << n) - 1);
    return 1;
}
