/* ---- SW-1106 zoomit64: RegSet/RegDeleteKeyValueW routed through the
 * existing in-memory hive (RegCreateKeyExW + RegSetValueExW /
 * RegOpenKeyExW + RegDeleteValueW). ---- */
__attribute__((ms_abi)) int32_t mw_RegSetValueExW(void* key, const wchar_t* name, uint32_t res, uint32_t type, const void* data, uint32_t size); /* fwd: defined below */
__attribute__((ms_abi)) int32_t mw_RegSetKeyValueW(void* key, const uint16_t* sub, const uint16_t* name, uint32_t type, const void* data, uint32_t size) {
    void* k = key;
    uint32_t r;
    if (sub && sub[0]) {
        r = (uint32_t)mw_RegCreateKeyExW(key, (const wchar_t*)sub, 0, NULL, 0, 0x000F0000u /*KEY_ALL_ACCESS*/, NULL, &k, NULL);
        if (r != 0) return (int32_t)r;
    }
    r = (uint32_t)mw_RegSetValueExW(k, (const wchar_t*)(name ? name : (const uint16_t*)L""), 0, type, data, size);
    if (k != key) mw_RegCloseKey(k);
    MW_TRACE("RegSetKeyValueW -> %u", r);
    return (int32_t)r;
}
__attribute__((ms_abi)) int32_t mw_RegDeleteKeyValueW(void* key, const uint16_t* sub, const uint16_t* name) {
    if (!name) { mw_SetLastError(87); return 87; }
    void* k = key;
    uint32_t r;
    if (sub && sub[0]) {
        r = (uint32_t)mw_RegOpenKeyExW(key, (const wchar_t*)sub, 0, 0x000F0000u, &k);
        if (r != 0) return (int32_t)r;
    }
    r = (uint32_t)mw_RegDeleteValueW(k, (const wchar_t*)name);
    if (k != key) mw_RegCloseKey(k);
    MW_TRACE("RegDeleteKeyValueW -> %u", r);
    return (int32_t)r;
}
__attribute__((ms_abi)) int32_t mw_RegSetValueExW(void* key, const wchar_t* name, uint32_t res, uint32_t type, const void* data, uint32_t size) {
    (void)res;
    int i = mw_reg_slot(key);
    if (i < 0) { mw_SetLastError(6); return 6; }
    if (size > MW_REG_DATA) { mw_SetLastError(234); return 234; }
    /* SWEEP-023 SW-992: overwrite the existing value (Windows contract); the
     * old append-only path made double-writes read back the FIRST value. */
    static const uint16_t empty_name[1] = {0};
    const uint16_t* nm = name ? (const uint16_t*)name : empty_name;
    for (uint32_t e = 0; e < g_reg[i].nvals; e++) {
        if (!mw_reg_weq(g_reg[i].vals[e].name, nm)) continue;
        MwRegVal* v = &g_reg[i].vals[e];
        v->type = type;
        v->size = size;
        if (size && data) memcpy(v->data, data, size);
        MW_TRACE("RegSetValueExW -> slot %d value overwritten (%u bytes)", i, size);
        return 0;
    }
    if (g_reg[i].nvals >= MW_REG_MAXVAL) { mw_SetLastError(14); return 14; }
    MwRegVal* v = &g_reg[i].vals[g_reg[i].nvals];
    mw_reg_wcopy(v->name, nm, MW_REG_VALN);
    v->type = type;
    v->size = size;
    if (size && data) memcpy(v->data, data, size);
    g_reg[i].nvals++;
    MW_TRACE("RegSetValueExW -> slot %d, %u bytes stored", i, size);
    return 0;
}
