/* SWEEP-013: system control-class detection. Guests pass either a
 * MAKEINTATOM class code (BUTTON=0x8080..COMBOBOX=0x8085 on x64) or a
 * wide/ascii class-name string ("Button", "Edit", ...). Returns 0x80..0x85
 * for a system control class, 0 otherwise. Guest memory is probed, never
 * dereferenced raw (BUG-066 discipline). */
static int mw_sysclass_w(const void* cls) {
    uintptr_t v = (uintptr_t)cls;
    if (v && v < 0x10000u) {
        if ((v & 0xFF00u) == 0x8000u) {
            uint32_t c = v & 0xFFu;
            if (c >= 0x80 && c <= 0x8D) return (int)c; /* SWEEP-019: +comctl children; SWEEP-021: +RICHEDIT; SW-1207: +tooltip */
        }
        return 0;
    }
    static const struct { const char* n; int c; } t[] = {
        {"button", 0x80}, {"edit", 0x81}, {"static", 0x82},
        {"listbox", 0x83}, {"scrollbar", 0x84}, {"combobox", 0x85},
        /* SWEEP-018: comctl children via CreateToolbarEx / CreateStatusWindow
         * (SW-803..806). Prefix match: toolbar* / msctls_statusbar32. */
        {"toolbar", 0x86}, {"msctls_statusbar32", 0x87},
        {"statuswindow", 0x87},
        /* SWEEP-019 SW-831..840: common-controls children (NirSoft main
         * lists, MFC trees, property sheets). Before this, a guest-created
         * SysListView32 got sc=0 and fell into the main-window path — the
         * LVM_* messages were never seen by any child model. */
        {"syslistview32", 0x88}, {"systreeview32", 0x89},
        {"systabcontrol32", 0x8A}, {"sysheader32", 0x8B},
        /* SWEEP-021 SW-906..910: RICHEDIT family (prefix covers 20W/50W) */
        {"richedit", 0x8C},
        /* SW-1207: comctl32 tooltip window class (popup AND owned forms;
         * prefix covers tooltips_class32 W/A). */
        {"tooltips_class32", 0x8D},
    };
    if (!cls) return 0;
    uint16_t tmp[16];
    if (!mw_probe_copy(cls, 30, tmp)) return 0;
    char a[16] = {0}; int i;
    for (i = 0; i < 15 && tmp[i]; i++)
        a[i] = (tmp[i] >= 'A' && tmp[i] <= 'Z') ? (char)(tmp[i] + 32) : (char)tmp[i];
    a[i] = 0;
    /* SWEEP-018: prefix compare clamped to the probe width (15) — matches
     * toolbar* and the 15-char-truncated msctls_statusbar32 probe. */
    for (i = 0; i < 15; i++) { /* SWEEP-021: 13 -> 14 (RICHEDIT); SW-1207: -> 15 (tooltip) */
        size_t L = strlen(t[i].n);
        if (strncmp(a, t[i].n, L < 15 ? L : 15) == 0) return t[i].c;
    }
    return 0;
}
static int mw_sysclass_a(const void* cls) {
    uintptr_t v = (uintptr_t)cls;
    if (v && v < 0x10000u) {
        if ((v & 0xFF00u) == 0x8000u) {
            uint32_t c = v & 0xFFu;
            if (c >= 0x80 && c <= 0x8D) return (int)c; /* SWEEP-019: +comctl children; SWEEP-021: +RICHEDIT; SW-1207: +tooltip */
        }
        return 0;
    }
    static const struct { const char* n; int c; } t[] = {
        {"button", 0x80}, {"edit", 0x81}, {"static", 0x82},
        {"listbox", 0x83}, {"scrollbar", 0x84}, {"combobox", 0x85},
        /* SWEEP-018: comctl children via CreateToolbarEx / CreateStatusWindow
         * (SW-803..806). Prefix match: toolbar* / msctls_statusbar32. */
        {"toolbar", 0x86}, {"msctls_statusbar32", 0x87},
        {"statuswindow", 0x87},
        /* SWEEP-019 SW-831..840: common-controls children (NirSoft main
         * lists, MFC trees, property sheets). Before this, a guest-created
         * SysListView32 got sc=0 and fell into the main-window path — the
         * LVM_* messages were never seen by any child model. */
        {"syslistview32", 0x88}, {"systreeview32", 0x89},
        {"systabcontrol32", 0x8A}, {"sysheader32", 0x8B},
        /* SWEEP-021 SW-906..910: RICHEDIT family (prefix covers 20W/50W) */
        {"richedit", 0x8C},
        /* SW-1207: comctl32 tooltip window class (prefix covers
         * tooltips_class32; the A probe truncates at 15 chars). */
        {"tooltips_class32", 0x8D},
    };
    if (!cls) return 0;
    char a[16] = {0}; int i;
    if (!mw_probe_copy(cls, 15, a)) return 0;
    for (i = 0; i < 15; i++)
        if (a[i] >= 'A' && a[i] <= 'Z') a[i] += 32;
    /* SWEEP-018: prefix compare clamped to the probe width (15). */
    for (i = 0; i < 15; i++) { /* SWEEP-021: 13 -> 14 (RICHEDIT); SW-1207: -> 15 (tooltip) */
        size_t L = strlen(t[i].n);
        if (strncmp(a, t[i].n, L < 15 ? L : 15) == 0) return t[i].c;
    }
    return 0;
}
static const char* mw_sysclass_name(int c) {
    static const char* n[] = {"BUTTON","EDIT","STATIC","LISTBOX","SCROLLBAR","COMBOBOX",
                              "TOOLBAR","STATUSBAR",
                              /* SWEEP-019 SW-831..840 */
                              "SysListView32","SysTreeView32","SysTabControl32","SysHeader32",
                              /* SWEEP-021 SW-906..910 */
                              "RICHEDIT",
                              /* SW-1207 */
                              "Tooltips_Class32"};
    return (c >= 0x80 && c <= 0x8D) ? n[c - 0x80] : "?";
}
/* Register one child-control identity; NULL when the 64-slot table is full. */
static void* mw_child_register(int sc, void* parent, void* menu,
                               const void* text, int wide, void* hwnd_out_cap) {
    (void)hwnd_out_cap;
    for (int i = 0; i < MW_CHILD_MAX; i++) {
        if (g_child[i].live) continue;
        g_child[i].live = 1;
        g_child[i].hwnd = (void*)(uintptr_t)(MW_CHILD_BASE + (uintptr_t)(i + 1));
        g_child[i].parent = parent;
        g_child[i].id = (uint32_t)(uintptr_t)menu; /* HMENU doubles as control id */
        g_child[i].checked = 0;
        g_child[i].enabled = 1;
        snprintf(g_child[i].cls, sizeof(g_child[i].cls), "%s", mw_sysclass_name(sc));
        if (text) {
            if (wide) mw_w16cpy(g_child[i].text, (const uint16_t*)text, 128);
            else {
                char a[128] = {0};
                if (mw_probe_copy(text, 127, a)) {
                    int j;
                    for (j = 0; j < 127 && a[j]; j++) g_child[i].text[j] = (uint16_t)(uint8_t)a[j];
                    g_child[i].text[j] = 0;
                }
            }
        }
        MW_TRACE("[GUI] child %s id=%lu -> HWND %p text='%u wchars'",
                 g_child[i].cls, (unsigned long)g_child[i].id, g_child[i].hwnd,
                 (unsigned)mw_w16len(g_child[i].text));
        return g_child[i].hwnd;
    }
    MW_TRACE("[GUI] child table full -> NULL");
    return NULL;
}
/* SW-1203: WH_CBT event delivery (defined after the hook machinery) */
int mw_hook_fire_create(uint32_t exstyle, uint32_t style, const void* winname,
        const void* clsname, int x, int y, int w, int h, void* parent,
        void* menu, void* inst, void* param);
void mw_hook_fire_destroy(void* hwnd);
void mw_hook_fire_activate(void* hwnd);

__attribute__((ms_abi)) int mw_SetPropW(void* h, const uint16_t* name, void* value); /* SW-1207 fwd */

__attribute__((ms_abi)) void* mw_CreateWindowExW(uint32_t exstyle, const void* cls,
        const uint16_t* win, uint32_t style, int x, int y, int w, int h,
        void* parent, void* menu, void* inst, void* param) {
    int sc = mw_sysclass_w(cls);
    /* SW-1207: comctl32 tooltips_class32 window object. Before this, a
     * tooltip call (popup parent=NULL OR owned) fell into the main-window
     * path and returned MW_GUI_HWND — rammap64 then did
     * GetPropW(tooltip, atom 0xC000) -> NULL and crashed inside its own
     * comctl32 subclass branch (RVA 0x1cfa9, mov rcx,[0x120] via RAX=0).
     * Real comctl32: the tooltip window proc subclasses itself during
     * WM_NCCREATE and stores SUBCLASS_INFO under global atom 0xC000
     * ("CC32SubclassInfo") BEFORE CreateWindowEx returns — the guest's
     * GetPropW(0xC000) must find a real block. Mint a DISTINCT identity
     * and perform that contract with a registered zeroed 0x140-byte block
     * (SUBCLASS_INFO-sized; zero counts = "no subclass frames"). */
    if (sc == 0x8D) {
        void* th = mw_child_register(sc, parent ? parent : MW_GUI_HWND, menu, win, 1, NULL);
        if (th) {
            void* si = mw_GlobalAlloc(0x40 /* GMEM_ZEROINIT */, 0x140);
            if (si) mw_SetPropW(th, (const uint16_t*)(uintptr_t)0xC000, si);
            MW_TRACE("[GUI] tooltips_class32 (ex=0x%x style=0x%x) -> HWND %p subclass-prop 0xC000 = %p",
                     exstyle, style, th, si);
        }
        return th;
    }
    if (sc && parent) { /* SWEEP-013: child control — engine-internal wndproc */
        (void)exstyle; (void)x; (void)y; (void)style;
        return mw_child_register(sc, parent, menu, win, 1, NULL);
    }
    /* SW-1203: WH_CBT pre-create notification — nonzero CANCELS (real CBT) */
    if (mw_hook_fire_create(exstyle, style, win, cls, x, y, w, h, parent, menu, inst, param))
        return NULL;
    g_create_param = param; /* SW-802..806: forward lpParam into CREATESTRUCT */
    mw_gui_store_window((int)w, (int)h); /* SWEEP-005: allocate paint surface */
    mw_gui_send_create(); /* SWEEP-006: synchronous WM_CREATE */
    MW_TRACE("CreateWindowExW(ex=0x%x style=0x%x cls=%p %dx%d@%d,%d) -> HWND %p",
             exstyle, style, cls, w, h, x, y, MW_GUI_HWND);
    return MW_GUI_HWND;
}
__attribute__((ms_abi)) void* mw_CreateWindowExA(uint32_t exstyle, const void* cls,
        const char* win, uint32_t style, int x, int y, int w, int h,
        void* parent, void* menu, void* inst, void* param) {
    int sc = mw_sysclass_a(cls);
    /* SW-1207: tooltip branch on the A path — same contract as the W path
     * above (distinct identity + CC32SubclassInfo prop at atom 0xC000). */
    if (sc == 0x8D) {
        void* th = mw_child_register(sc, parent ? parent : MW_GUI_HWND, menu, win, 0, NULL);
        if (th) {
            void* si = mw_GlobalAlloc(0x40 /* GMEM_ZEROINIT */, 0x140);
            if (si) mw_SetPropW(th, (const uint16_t*)(uintptr_t)0xC000, si);
            MW_TRACE("[GUI] tooltips_class32A (ex=0x%x style=0x%x) -> HWND %p subclass-prop 0xC000 = %p",
                     exstyle, style, th, si);
        }
        return th;
    }
    if (sc && parent) { /* SWEEP-013: child control — engine-internal wndproc */
        (void)exstyle; (void)x; (void)y; (void)style;
        return mw_child_register(sc, parent, menu, win, 0, NULL);
    }
    /* SW-1203: WH_CBT pre-create notification — nonzero CANCELS (real CBT);
     * the A path passes the ANSI name reinterpreted — hooks read names
     * through the same pointer the caller would have used on Windows. */
    if (mw_hook_fire_create(exstyle, style, win, cls, x, y, w, h, parent, menu, inst, param))
        return NULL;
    g_create_param = param; /* SW-802..806: forward lpParam into CREATESTRUCT */
    mw_gui_store_window((int)w, (int)h); /* SWEEP-005: allocate paint surface */
    mw_gui_send_create(); /* SWEEP-006: synchronous WM_CREATE */
    MW_TRACE("CreateWindowExA(ex=0x%x style=0x%x cls=%p %dx%d@%d,%d) -> HWND %p",
             exstyle, style, cls, w, h, x, y, MW_GUI_HWND);
    return MW_GUI_HWND;
}
