__attribute__((ms_abi)) uint32_t mw_RtlNtStatusToDosError(uint32_t st) {
    switch (st) {
    case 0: return 0;
    case NTSTATUS_OBJECT_NAME_NOT_FOUND: return 2;  /* ERROR_FILE_NOT_FOUND */
    case NTSTATUS_INVALID_HANDLE:        return 6;  /* ERROR_INVALID_HANDLE */
    case NTSTATUS_ACCESS_DENIED:         return 5;  /* ERROR_ACCESS_DENIED */
    case NTSTATUS_INVALID_INFO_CLASS:    return 87; /* ERROR_INVALID_PARAMETER */
    case NTSTATUS_INVALID_PARAMETER:     return 87;
    default: return 31;                             /* ERROR_GEN_FAILURE */
    }
}

/* ---- advapi32: SID allocation (real SID bytes) + token queries + SCM ---- */
static void* g_sid_alloc[16];
__attribute__((ms_abi)) int mw_AllocateAndInitializeSid(const void* auth, uint8_t count,
        uint32_t s0, uint32_t s1, uint32_t s2, uint32_t s3,
        uint32_t s4, uint32_t s5, uint32_t s6, uint32_t s7, void** psid) {
    if (!auth || !psid || count == 0 || count > 8) return 0;
    uint8_t a[8];
    if (!mw_probe_copy(auth, 6, a)) return 0;
    uint8_t* p = (uint8_t*)malloc((size_t)8 + 4u * count);
    if (!p) return 0;
    p[0] = 1;            /* Revision */
    p[1] = count;        /* SubAuthorityCount */
    memcpy(p + 2, a, 6); /* IdentifierAuthority */
    uint32_t subs[8] = { s0, s1, s2, s3, s4, s5, s6, s7 };
    for (uint8_t i = 0; i < count; i++)
        *(uint32_t*)(p + 8 + 4u * i) = subs[i];
    *psid = p;
    for (int i = 0; i < 16; i++)
        if (!g_sid_alloc[i]) { g_sid_alloc[i] = p; break; }
    MW_TRACE("AllocateAndInitializeSid(count=%u) -> SID %p", count, (void*)p);
    return 1;
}
__attribute__((ms_abi)) void* mw_FreeSid(void* sid) {
    if (sid)
        for (int i = 0; i < 16; i++)
            if (g_sid_alloc[i] == sid) { g_sid_alloc[i] = NULL; break; }
    free(sid);
    MW_TRACE("FreeSid(%p) -> NULL", sid);
    return NULL;
}
__attribute__((ms_abi)) int mw_EqualSid(const void* a, const void* b) {
    uint8_t x[40], y[40];
    if (!a || !b || !mw_probe_copy(a, 40, x) || !mw_probe_copy(b, 40, y)) return 0;
    if (x[0] != 1 || y[0] != 1) return 0;
    size_t n = 8 + 4u * (x[1] < y[1] ? x[1] : y[1]);
    return memcmp(x, y, n) == 0;
}
/* SWEEP-026: session SIDs lifted to file scope so the SW-1041..1045/1095
 * family (GetSecurityInfo, CheckTokenMembership, WellKnownSid, wide-name
 * SetEntriesInAclW) shares ONE identity model with GetTokenInformation. */
static uint8_t g_mw_user_sid[28] = {
    1, 5, 0, 0, 0, 0, 0, 5,              /* rev 1, count 5, IA=5 */
    21, 0, 0, 0,                          /* S-1-5-21-... */
    100, 0, 0, 0, 200, 1, 0, 0,
    50, 1, 0, 0, 232, 3, 0, 0
};
static uint8_t g_mw_admins_sid[16] = {
    1, 2, 0, 0, 0, 0, 0, 5, 32, 0, 0, 0, 32, 2, 0, 0 /* S-1-5-32-544 */
};
__attribute__((ms_abi)) int mw_GetTokenInformation(void* token, uint32_t cls, void* info,
        uint32_t len, uint32_t* retlen) {
    (void)token; /* process pseudo-token: any handle maps to our session token */
    if (retlen) *retlen = 0;
    /* Standard two-call size query: info==NULL asks for the required size
     * (answer FALSE + ERROR_INSUFFICIENT_BUFFER + *retlen = size). */
    if (!info) {
        uint32_t need = (cls == 1) ? 16u : (cls == 2) ? 20u : 0u;
        if (need) { if (retlen) *retlen = need; mw_SetLastError(122); return 0; }
        mw_SetLastError(87);
        return 0;
    }
    /* cls==1 TokenUser: the session user SID (pageant get_user_sid path).
     * TOKEN_USER x64 = { PSID Sid @0, ULONG Attributes @8 } = 16 bytes. */
    if (cls == 1) {
        if (len < 16) { if (retlen) *retlen = 16; mw_SetLastError(122); return 0; }
        *(void**)info = g_mw_user_sid;
        *(uint32_t*)((uint8_t*)info + 8) = 0;
        if (retlen) *retlen = 16;
        MW_TRACE("GetTokenInformation(TokenUser) -> S-1-5-21-...-1000 TRUE");
        return 1;
    }
    /* cls==2 TokenGroups: the engine's session token model is "elevated
     * Administrator" (consistent with AllocateAndInitializeSid(S-1-5-32-544)
     * + EqualSid chains procmon64 runs right before this). One group:
     * BUILTIN\Administrators, SE_GROUP_MANDATORY|ENABLED|ENABLED_BY_DEFAULT.
     * TOKEN_GROUPS x64: GroupCount u32, Groups[1] = {PSID 8, attr u32+pad4}. */
    if (cls == 2) {
        if (len < 20) { if (retlen) *retlen = 20; mw_SetLastError(122); return 0; }
        *(uint32_t*)info = 1;
        *(void**)((uint8_t*)info + 8) = (void*)g_mw_admins_sid;
        *(uint32_t*)((uint8_t*)info + 16) = 0xEu; /* MANDATORY|ENABLED|ENABLED_BY_DEFAULT */
        if (retlen) *retlen = 20;
        MW_TRACE("GetTokenInformation(TokenGroups) -> 1 group (S-1-5-32-544) TRUE");
        return 1;
 }
    if (cls == 18) { /* TokenElevationType */
        if (len < 4) return 0;
        *(uint32_t*)info = 3; /* TokenElevationTypeLimited — non-elevated headless session */
        if (retlen) *retlen = 4;
        MW_TRACE("GetTokenInformation(ElevationType) -> 3 (limited) TRUE");
        return 1;
    }
    if (cls == 20) { /* TokenElevation (TOKEN_ELEVATION) */
        if (len < 8) return 0;
        *(uint32_t*)info = 3;     /* TokenType = limited */
        *(uint32_t*)((uint8_t*)info + 4) = 0; /* TokenIsElevated = FALSE */
        if (retlen) *retlen = 8;
        MW_TRACE("GetTokenInformation(TokenElevation) -> not-elevated TRUE");
        return 1;
    }
    MW_TRACE("GetTokenInformation(class=%lu) -> FALSE (ERROR_INVALID_PARAMETER)",
             (unsigned long)cls);
    mw_SetLastError(87);
    return 0;
}
