__attribute__((ms_abi)) int16_t mw_SQLDescribeCol(void* stmt, uint16_t col, uint16_t* name,
        int16_t namelen, int16_t* namelenOut, int16_t* dtype, uint32_t* size,
        int16_t* digits, int16_t* nullable) {
    int s = mw_odbc_slot((uintptr_t)stmt, MW_ODBC_STMT_BASE);
    if (s < 0 || !g_odbc_stmt[s].live) return (int16_t)MW_SQL_INVALID_HANDLE;
    sqlite3_stmt* st = g_odbc_stmt[s].st;
    if (namelenOut) *namelenOut = 0;
    if (name && namelen > 0) name[0] = 0;
    if (dtype) *dtype = (int16_t)MW_SQL_CHAR;
    if (size) *size = 255;
    if (digits) *digits = 0;
    if (nullable) *nullable = 1; /* SQL_NULLABLE */
    if (!st || col < 1 || (int)col > sqlite3_column_count(st)) return (int16_t)MW_SQL_ERROR;
    int c = col - 1;
    const void* nm = sqlite3_column_name16(st, c);
    if (nm && name && namelen > 0) {
        const uint16_t* w = (const uint16_t*)nm;
        int n = 0;
        while (w[n]) n++;
        int cp = n < namelen - 1 ? n : namelen - 1;
        memcpy(name, w, (size_t)cp * 2);
        name[cp] = 0;
        if (namelenOut) *namelenOut = (int16_t)n;
    }
    if (dtype) {
        int t = sqlite3_column_type(st, c);
        *dtype = (int16_t)(t == SQLITE_INTEGER ? MW_SQL_INTEGER
                         : t == SQLITE_FLOAT ? MW_SQL_DOUBLE
                         : MW_SQL_CHAR);
    }
    return (int16_t)MW_SQL_SUCCESS;
}
__attribute__((ms_abi)) int16_t mw_SQLGetDiagRecW(int16_t type, void* h, int16_t rec,
        uint16_t* state, int32_t* native, uint16_t* msg, int16_t msglen, int16_t* retlen) {
    sqlite3* db = NULL;
    if (type == MW_SQL_HANDLE_DBC && mw_odbc_is_dbc(h)) {
        int d = mw_odbc_slot((uintptr_t)h, MW_ODBC_DBC_BASE);
        if (d >= 0) db = g_odbc_dbc[d].db;
    } else if (type == MW_SQL_HANDLE_STMT && mw_odbc_is_stmt(h)) {
        int s = mw_odbc_slot((uintptr_t)h, MW_ODBC_STMT_BASE);
        if (s >= 0) db = g_odbc_stmt[s].db;
    }
    if (!db || rec != 1) return (int16_t)MW_SQL_NO_DATA; /* no diagnostic source */
    if (state) { /* SQLSTATE class HY000 = driver-defined error */
        state[0] = 'H'; state[1] = 'Y'; state[2] = '0'; state[3] = '0'; state[4] = 0;
    }
    if (native) *native = sqlite3_errcode(db);
    if (msg && msglen > 0) {
        const uint16_t* e = (const uint16_t*)sqlite3_errmsg16(db);
        int n = 0;
        while (e && e[n]) n++;
        int cp = n < msglen - 1 ? n : msglen - 1;
        memcpy(msg, e, (size_t)cp * 2);
        msg[cp] = 0;
        if (retlen) *retlen = (int16_t)n;
    } else if (retlen) *retlen = 0;
    return (int16_t)MW_SQL_SUCCESS;
}

/* ---- OLEAUT32 raw-ordinal tail (winmergeu) ---- */
__attribute__((ms_abi)) uint32_t mw_SafeArrayPutElement(void* sa, int32_t* idx, void* data) {
    int s = mw_sa_slot(sa);
    if (!idx || !data) return 0x80070057u; /* E_INVALIDARG */
    if (s < 0) return 0x8002000Bu;
    int64_t flat = mw_sa_flat(s, idx);
    if (flat < 0) return 0x8002000Bu;
    memcpy(g_sa[s].data + (size_t)flat * g_sa[s].elemsz, data, g_sa[s].elemsz);
    MW_TRACE("[OLE] SafeArrayPutElement(%p [%d,%d]) vt=%u", sa, idx[0],
             g_sa[s].dims > 1 ? idx[1] : 0, g_sa[s].vt);
    return 0; /* S_OK */
}
__attribute__((ms_abi)) uint32_t mw_SafeArrayGetElement(void* sa, int32_t* idx, void* out) {
    int s = mw_sa_slot(sa);
    if (!idx || !out) return 0x80070057u;
    if (s < 0) return 0x8002000Bu;
    int64_t flat = mw_sa_flat(s, idx);
    if (flat < 0) return 0x8002000Bu;
    memcpy(out, g_sa[s].data + (size_t)flat * g_sa[s].elemsz, g_sa[s].elemsz);
    return 0; /* S_OK */
}
__attribute__((ms_abi)) uint32_t mw_SafeArrayDestroy(void* sa) {
    int s = mw_sa_slot(sa);
    if (s < 0) return 0x80070057u; /* E_INVALIDARG */
    free(g_sa[s].data);
    g_sa[s].data = NULL;
    g_sa[s].live = 0;
    MW_TRACE("[OLE] SafeArrayDestroy(%p)", sa);
    return 0; /* S_OK */
}

/* SWEEP-037 (SW-1225): oleaut32!VarUI4FromStr — REAL parse (wine spec
 * ordinal 277, procexp64 binds it raw). HRESULT semantics: S_OK,
 * E_INVALIDARG on NULL out, DISP_E_TYPEMISMATCH on non-digit/overflow.
 * Windows accepts embedded sign for UI4? No: VT_UI4 from string is
 * unsigned-only; whitespace tolerated per VarParse. */
__attribute__((ms_abi)) uint32_t mw_VarUI4FromStr(const uint16_t* str, uint32_t lcid, uint32_t flags, uint32_t* out) {
    (void)lcid; (void)flags;
    if (!out) return 0x80070057u; /* E_INVALIDARG */
    *out = 0;
    if (!str) return 0x80070057u;
    uint64_t v = 0;
    int any = 0;
    for (uint32_t i = 0; str[i]; i++) {
        uint16_t c = str[i];
        if (c == (uint16_t)' ' || c == (uint16_t)'\t') continue; /* VarParse skips ws */
        if (c < (uint16_t)'0' || c > (uint16_t)'9') return 0x80020005u; /* DISP_E_TYPEMISMATCH */
        v = v * 10 + (uint64_t)(c - (uint16_t)'0');
        if (v > 0xFFFFFFFFull) return 0x80020005u; /* overflow: TYPEMISMATCH */
        any = 1;
    }
    if (!any) return 0x80020005u;
    *out = (uint32_t)v;
    MW_TRACE("[OLEAUT] VarUI4FromStr -> %u", *out);
    return 0; /* S_OK */
}

__attribute__((ms_abi)) uint32_t mw_VarBstrFromDate(double date, uint32_t lcid, uint32_t flags, void** bstrOut) {
    (void)lcid; (void)flags;
    if (!bstrOut) return 0x80070057u; /* E_INVALIDARG */
    char buf[64];
    snprintf(buf, sizeof buf, "%.6f", date);
    uint16_t w[64];
    size_t n = 0;
    for (; buf[n] && n < 63; n++) w[n] = (uint16_t)(uint8_t)buf[n];
    w[n] = 0;
    *bstrOut = bstr_alloc_len(w, (uint32_t)n); /* v1: invariant numeric form */
    return 0; /* S_OK */
}
